questions.solution:
function realPort(address) {
  const url = new URL(address);
  if (url.port !== "") return Number(url.port);
  if (url.protocol === "https:") return 443;
  return 80;
}

console.log(realPort("https://shop.example.com/cart"), realPort("http://example.com/"), realPort("http://localhost:8080/tasks"));

