function isSafeForPasswords(address) {
  const url = new URL(address);
  if (url.protocol === "https:") return true;
  return url.hostname === "localhost";
}

console.log(
  isSafeForPasswords("https://api.myapp.com/login"),
  isSafeForPasswords("http://localhost:3000/login"),
  isSafeForPasswords("http://api.myapp.com/login"),
);

